{"code":"import re, glob, json, html as H

rows = []
for f in sorted(glob.glob("/root/.hermes/cache/scratch/fc_*_*.html")):
    vendor = f.split("fc_")[1].split("_")[0]
    page = f.split("_")[-1].split(".")[0]
    txt = open(f, encoding="utf-8", errors="ignore").read()
    items = re.findall(r'data-customer-name="([^"]*)"[\s\S]{0,400}?data-title="([^"]*)"', txt)
    for name, title in items:
        rows.append({"vendor": vendor, "page": page, "customer": H.unescape(name), "title": H.unescape(title)})

print("total rows:", len(rows))
uniq = {}
for r in rows:
    uniq.setdefault(r["customer"].lower(), r)
print("unique customers:", len(uniq))
json.dump(list(uniq.values()), open("/root/.hermes/cache/scratch/fc_customers.json","w"), indent=1)
for c, r in sorted(uniq.items()):
    print(f'{r["vendor"]:12s} | {r["customer"]}')
